package mongodb

// InsertOneResult is the result of Collection.InsertOne, the gem's
// Mongo::Operation::Result for an insert. InsertedID is the _id of the inserted
// document (an ObjectId generated by the driver when the document had none).
type InsertOneResult struct {
	InsertedID any
}

// InsertManyResult is the result of Collection.InsertMany. InsertedIDs holds the
// _id of each inserted document, in input order.
type InsertManyResult struct {
	InsertedIDs []any
}

// UpdateResult is the result of an update, replace, or upsert, mirroring the
// counts the gem exposes on Mongo::Operation::Result.
type UpdateResult struct {
	MatchedCount  int64 // documents matched by the filter
	ModifiedCount int64 // documents actually modified
	UpsertedCount int64 // documents inserted by an upsert (0 or 1)
	UpsertedID    any   // _id of an upserted document, or nil
}

// DeleteResult is the result of a delete. DeletedCount is the number of
// documents removed.
type DeleteResult struct {
	DeletedCount int64
}
